import { z } from 'zod';
import type { MemberRef } from './issues.js';

/**
 * Whiteboards (SPEC §5.5, ADR 0015): collaborative canvases of a team, edited by several
 * people at once and attachable to issues. Elements use the Excalidraw element format.
 */

/** Element ids are generated by the editor (nanoid) or by Ordler for diagrams from MCP. */
export const whiteboardElementIdSchema = z
  .string()
  .min(1)
  .max(64)
  .regex(/^[A-Za-z0-9_-]+$/);

/** Upper bound of a single element's JSON; long freehand strokes stay far below it. */
export const WHITEBOARD_MAX_ELEMENT_BYTES = 512 * 1024;
/** Elements one save may carry; the editor sends small batches many times a second. */
export const WHITEBOARD_MAX_BATCH = 1000;
/** Elements a board may hold, deleted ones included (they are needed to converge). */
export const WHITEBOARD_MAX_ELEMENTS = 20_000;
/** Image types a board accepts; they are only ever shown through <img>, never as a page. */
export const WHITEBOARD_IMAGE_TYPES = [
  'image/png',
  'image/jpeg',
  'image/gif',
  'image/webp',
  'image/svg+xml',
] as const;

/**
 * One canvas element. Only the fields the server reasons about are checked; the rest of the
 * element is kept as-is and normalised by the editor when loaded.
 */
export const whiteboardElementSchema = z.looseObject({
  id: whiteboardElementIdSchema,
  type: z.string().min(1).max(40),
  version: z.number().int().min(1).max(2_147_483_647),
  versionNonce: z.number().int().min(-2_147_483_648).max(2_147_483_647),
  isDeleted: z.boolean().default(false),
});
export type WhiteboardElement = z.infer<typeof whiteboardElementSchema>;

/** POST /api/whiteboards/:id/scene */
export const whiteboardSceneUpdateSchema = z.object({
  elements: z.array(whiteboardElementSchema).min(1).max(WHITEBOARD_MAX_BATCH),
});
export type WhiteboardSceneUpdate = z.input<typeof whiteboardSceneUpdateSchema>;

/** GET /api/whiteboards/:id/scene?since=<seq>: elements changed after `since` (0 = all). */
export interface WhiteboardScene {
  /** Highest change number included; pass it as `since` to catch up later. */
  seq: number;
  elements: WhiteboardElement[];
}

/** POST /api/whiteboards/:id/files: an image placed on the board. */
export const whiteboardFileSchema = z.object({
  id: z
    .string()
    .min(1)
    .max(128)
    .regex(/^[A-Za-z0-9_-]+$/),
  mimeType: z.enum(WHITEBOARD_IMAGE_TYPES),
  /** `data:<mime>;base64,<bytes>` as the editor produces it. */
  dataURL: z.string().min(1),
});
export type WhiteboardFileInput = z.infer<typeof whiteboardFileSchema>;

export interface WhiteboardFile {
  id: string;
  mimeType: string;
  dataURL: string;
  created: number;
}

export const whiteboardCreateSchema = z.object({
  team: z.string().trim().min(1).max(10),
  title: z.string().trim().min(1).max(200),
  /** Attach the new board to this issue right away (the issue page's "New whiteboard"). */
  issue: z.string().trim().min(3).max(40).optional(),
});
export type WhiteboardCreate = z.input<typeof whiteboardCreateSchema>;

export const whiteboardUpdateSchema = z.object({
  title: z.string().trim().min(1).max(200),
});
export type WhiteboardUpdate = z.input<typeof whiteboardUpdateSchema>;

/** POST /api/issues/:identifier/whiteboards */
export const issueWhiteboardLinkSchema = z.object({
  whiteboardId: z.uuid(),
});

export interface WhiteboardSummary {
  id: string;
  title: string;
  team: { id: string; key: string; name: string };
  createdBy: MemberRef | null;
  createdAt: string;
  updatedAt: string;
  /** May draw on it: `whiteboard.edit` on the team. */
  canEdit: boolean;
  /** May rename and delete it: its creator with `whiteboard.edit`, or `team.update`. */
  canManage: boolean;
}

export interface WhiteboardView extends WhiteboardSummary {
  /** Issues it is attached to that the member can read. */
  issues: Array<{ identifier: string; title: string }>;
}

/** Someone else's pointer and selection, shown live on the canvas. */
export interface WhiteboardPresence {
  /** One per open tab, so the same member in two tabs shows twice. */
  clientId: string;
  member: MemberRef;
  pointer: { x: number; y: number; tool: 'pointer' | 'laser' } | null;
  button: 'up' | 'down';
  selectedElementIds: string[];
  /** The tab closed or left the board. */
  left?: boolean;
}

export const whiteboardPresenceSchema = z.object({
  type: z.literal('presence'),
  topic: z.string().max(100),
  pointer: z
    .object({
      x: z.number().finite(),
      y: z.number().finite(),
      tool: z.enum(['pointer', 'laser']).default('pointer'),
    })
    .nullable(),
  button: z.enum(['up', 'down']).default('up'),
  selectedElementIds: z.array(whiteboardElementIdSchema).max(50).default([]),
});
export type WhiteboardPresenceMessage = z.input<typeof whiteboardPresenceSchema>;

export function whiteboardTopic(id: string): string {
  return `whiteboard:${id}`;
}

/** Shapes an agent can place through MCP; mapped to editor elements by the server. */
export const DIAGRAM_SHAPES = ['rectangle', 'ellipse', 'diamond', 'sticky', 'text'] as const;
export const DIAGRAM_COLORS = [
  'gray',
  'yellow',
  'blue',
  'green',
  'red',
  'purple',
  'orange',
] as const;
